import heapq

def func(nums, k):
    frequency = {}
    for sublist in nums:
        for num in sublist:
            frequency[num] = frequency.get(num, 0) + 1

    heap = [(-freq, num) for num, freq in frequency.items()]
    heapq.heapify(heap)

    top_k = []
    for _ in range(k):
        if not heap:
            break
        neg_freq, num = heapq.heappop(heap)
        top_k.append((-neg_freq, num))

    # Sort by frequency ascending, then number ascending to get the required order
    top_k_sorted = sorted(top_k, key=lambda x: (x[0], x[1]))
    return [num for (freq, num) in top_k_sorted]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, func([[1, 2, 6], [1,3,4,5,7,8], [1,3,5,6,8,9], [2,5,7,11], [1,4,7,8,12]], 3), [5,7,1])
    check(2, func([[1,2], [3,4]], 2), [1,2])  # Corrected expected value
    check(3, func([[5,5]], 1), [5])
    check(4, func([[], [1,1,1]], 1), [1])

def max_Prime_Factors(n):
    if n <= 1:
        return 0
    max_prime = -1
    i = 2
    while i * i <= n:
        while n % i == 0:
            max_prime = i
            n = n // i
        i += 1
    if n > 1:
        max_prime = max(max_prime, n)
    return max_prime

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
