    check(2, max_Prime_Factors(7), 7)
    check(3, max_Prime_Factors(8), 2)
    check(4, max_Prime_Factors(6), 3)
    check(5, max_Prime_Factors(17), 17)
    check(6, max_Prime_Factors(100), 5)
    check(7, max_Prime_Factors(2), 2)

