def max_len_sub(arr, n):
    if n == 0:
        return 0
    max_len = 1
    start = 0
    prev_decrease = -1
    current_decreases = 0
    for i in range(1, n):
        if arr[i] < arr[i-1]:
            current_decreases += 1
            if current_decreases == 1:
                prev_decrease = i-1
            elif current_decreases > 1:
                start = prev_decrease + 1
                current_decreases = 1
                prev_decrease = i-1
        current_length = i - start + 1
        if current_length > max_len:
            max_len = current_length
    return max_len

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

