def get_Char(strr):
    total = 0
    for c in strr:
        lower_c = c.lower()
        if 'a' <= lower_c <= 'z':
            total += ord(lower_c) - ord('a') + 1
    mod = total % 26
    if mod == 0:
        mod = 26
    return chr(ord('a') + mod - 1)

