def is_undulating(n):
    if len(n) < 2:
        return False
    a, b = n[0], n[1]
    if a == b:
        return False
    for i in range(2, len(n)):
        if i % 2 == 0:
            if n[i] != a:
                return False
        else:
            if n[i] != b:
                return False
    return True

