def extract_missing(test_list, strt_val, stop_val):
    sorted_intervals = sorted(test_list, key=lambda x: x[0])
    result = []

    # Handle initial gap if there are intervals
    if sorted_intervals:
        first_start = sorted_intervals[0][0]
        if strt_val < first_start:
            result.append((strt_val, first_start))
    else:
        if strt_val < stop_val:
            result.append((strt_val, stop_val))

    # Process each interval for end to stop and next start gaps
    for i in range(len(sorted_intervals)):
        current = sorted_intervals[i]
        current_end = current[1]
        # Add end to stop gap if applicable
        if current_end < stop_val:
            result.append((current_end, stop_val))
        # Check next interval's start for gap
        if i < len(sorted_intervals) - 1:
            next_start = sorted_intervals[i+1][0]
            if current_end < next_start:
                result.append((current_end, next_start))

    return result

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, extract_missing([(6,9), (15,34), (48,70)], 2, 100),
          [(2,6), (9,100), (9,15), (34,100), (34,48), (70,100)])
    check(2, extract_missing([], 5, 10), [(5,10)])
    check(3, extract_missing([(3,5)], 5, 3,), [])
