import math

def amicable_numbers_sum(limit):
    def sum_proper(n):
        if n <= 1:
            return 0
        total = 1
        sqrt_n = int(math.sqrt(n))
        for i in range(2, sqrt_n +1):
            if n % i == 0:
                total += i
                other = n // i
                if other != i:
                    total += other
        return total

    amicable = set()
    for a in range(1, limit):
        s = sum_proper(a)
        if s < 1 or s >= limit:
            continue
        if a != s and sum_proper(s) == a:
            amicable.add(a)
    return sum(amicable)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
