def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0:
        return False
    for row in my_matrix:
        if len(row) != n:
            return False
    elements = []
    for row in my_matrix:
        elements.extend(row)
    if len(elements) != n * n:
        return False
    required = set(range(1, n * n + 1))
    if set(elements) != required:
        return False
    magic = n * (n**2 + 1) // 2
    for row in my_matrix:
        if sum(row) != magic:
            return False
    for col in range(n):
        col_sum = sum(row[col] for row in my_matrix)
        if col_sum != magic:
            return False
    diag1 = sum(my_matrix[i][i] for i in range(n))
    diag2 = sum(my_matrix[i][n-1 -i] for i in range(n))
    if diag1 != magic or diag2 != magic:
        return False
    return True

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

