def pancake_sort(nums):
    arr = list(nums)
    n = len(arr)
    for i in range(n, 0, -1):
        max_part = arr[:i]
        max_val = max(max_part)
        max_idx = max_part.index(max_val)
        if max_idx != i - 1:
            if max_idx != 0:
                arr[:max_idx+1] = arr[:max_idx+1][::-1]
            arr[:i] = arr[:i][::-1]
    return arr

