def max_path_sum(tri, m, n):
    dp = tri[-1].copy()
    for i in range(len(tri)-2, -1, -1):
        current_row = tri[i]
        new_dp = []
        for j in range(len(current_row)):
            if j + 1 < len(dp):
                max_val = max(dp[j], dp[j+1])
            else:
                max_val = dp[j]
            new_dp.append(current_row[j] + max_val)
        dp = new_dp
    return dp[0]

