def merge(a):
    if len(a) <= 1:
        return a.copy()
    mid = len(a) // 2
    left = merge(a[:mid])
    right = merge(a[mid:])
    return merge_helper(left, right)

def merge_helper(a, b):
    merged = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
