def solution(a, b, n):
    max_x = n // a
    for x in range(max_x, -1, -1):
        remainder = n - a * x
        if remainder < 0:
            continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return None

