import math

def answer(L, R):
    # Check for a and 2a first
    for a in range(L, R + 1):
        if 2 * a <= R:
            return (a, 2 * a)
    # Check all pairs within L to R
    for a in range(L, R + 1):
        for b in range(a + 1, R + 1):
            gcd = math.gcd(a, b)
            lcm = (a * b) // gcd
            if L <= lcm <= R:
                return (a, b)
    # Fallback (assuming problem constraints ensure a solution exists)
    return (L, L + 1)  # This case should not occur under valid constraints

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, answer(3, 8), (3, 6))
    check(2, answer(5, 10), (5, 10))
    check(3, answer(2, 5), (2, 4))
    check(4, answer(4, 8), (4, 8))  # LCM 8 is within 4-8
    check(5, answer(3, 7), (3, 6))  # LCM 6 within 3-7

