import math

def prod_Square(n):
    if n < 0:
        return False
    s = math.isqrt(n)
    if s * s != n:
        return False
    k = s
    if k < 4:
        return False
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, math.isqrt(x) + 1):
            if x % i == 0:
                return False
        return True
    return not is_prime(k)

