def first(arr, x, n):
    low = 0
    high = n
    res = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            res = mid
            high = mid -1
        elif arr[mid] < x:
            low = mid +1
        else:
            high = mid -1
    return res

