def heap_replace(heap, a):
    new_heap = list(heap)
    if not new_heap:
        return [a]
    min_val = min(new_heap)
    min_index = new_heap.index(min_val)
    new_heap[min_index] = a
    n = len(new_heap)
    for i in reversed(range(n // 2)):
        current = i
        while True:
            left = 2 * current + 1
            right = 2 * current + 2
            smallest = current
            if left < n and new_heap[left] < new_heap[smallest]:
                smallest = left
            if right < n and new_heap[right] < new_heap[smallest]:
                smallest = right
            if smallest != current:
                new_heap[current], new_heap[smallest] = new_heap[smallest], new_heap[current]
                current = smallest
            else:
                break
    return new_heap

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, heap_replace([25,44,68,21,39,23,89], 21), [21,25,23,44,39,68,89])
    check(2, heap_replace([5,3,8],1), [1,5,8])
    check(3, heap_replace([3,2,1],0), [0,2,3])
    check(4, heap_replace([4,5,6,7],2), [2,5,6,7])

