def max_sum(tri, n):
    if n == 0:
        return 0
    dp = tri[-1].copy()
    for i in range(n-2, -1, -1):
        current_row = tri[i]
        new_dp = []
        for j in range(len(current_row)):
            max_next = max(dp[j], dp[j+1])
            new_dp.append(current_row[j] + max_next)
        dp = new_dp
    return dp[0]

