def get_total_number_of_sequences(m, n):
    if n == 0:
        return 0
    prev_dp = {x: 1 for x in range(1, m + 1)}
    if n == 1:
        return sum(prev_dp.values())

    for step in range(2, n + 1):
        current_dp = {}
        sorted_ys = sorted(prev_dp.keys())
        prefix = []
        current_sum = 0
        for y in sorted_ys:
            current_sum += prev_dp[y]
            prefix.append((y, current_sum))

        for x in range(1, m + 1):
            max_y = x // 2
            low, high = 0, len(sorted_ys) - 1
            best = -1
            while low <= high:
                mid = (low + high) // 2
                if sorted_ys[mid] <= max_y:
                    best = mid
                    low = mid + 1
                else:
                    high = mid - 1
            total = prefix[best][1] if best != -1 else 0
            if total > 0:
                current_dp[x] = total
        prev_dp = current_dp
        if not prev_dp:
            return 0

    return sum(prev_dp.values())

