def sort_on_occurence(lst):
    groups = {}
    order = []
    for tpl in lst:
        key = tpl[0]
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(tpl[1])
    result = []
    for key in order:
        elements = groups[key]
        count = len(elements)
        new_tuple = (key, *elements, count)
        result.append(new_tuple)
    return result

