def max_sum(arr, n):
    if n == 0:
        return 0
    inc = [0] * n
    dec = [0] * n

    # Compute increasing subsequence sums
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # Compute decreasing subsequence sums
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    max_total = 0
    for i in range(n):
        current = inc[i] + dec[i] - arr[i]
        if current > max_total:
            max_total = current
    return max_total

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

