def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Number must be non-negative")
    if number == 0:
        return 0.0
    x = number / 2.0
    while True:
        next_x = (x + number / x) / 2.0
        if abs(next_x - x) < 1e-12:
            return next_x
        x = next_x

