def newman_prime(n):
    """nth ডেলানয় সংখ্যা খুঁজে বের করার জন্য একটি ফাংশন লিখুন।
    Translated: Write a function to find the nth Newman–Shanks–Williams prime number.

    Args:
        n (int): Example: 3

    Returns:
        int: Example: 7

    Example:
        >>> newman_prime(3)
        7
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) +1, 2):
            if num % i ==0:
                return False
        return True

    primes = []
    a, b = 2, 1  # L0 and L1
    # Check L0
    if is_prime(a):
        primes.append(a)
    if len(primes) >= n:
        return primes[n-1]
    # Check L1
    if is_prime(b):
        primes.append(b)
    if len(primes) >= n:
        return primes[n-1]
    # Generate next terms
    while True:
        next_term = a + b
        if is_prime(next_term):
            primes.append(next_term)
        if len(primes) >= n:
            return primes[n-1]
        a, b = b, next_term

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, newman_prime(3), 7)
    check(2, newman_prime(1), 2)
    check(3, newman_prime(2), 3)
    check(4, newman_prime(4), 11)
    check(5, newman_prime(5), 29)

