def max_sub_array_sum_repeated(a, n, k):
    # Compute max_single using Kadane's algorithm
    if not a:
        return 0
    max_current = max_single = a[0]
    for num in a[1:]:
        max_current = max(num, max_current + num)
        max_single = max(max_single, max_current)

    # Compute max_prefix
    current_sum = 0
    max_prefix = float('-inf')
    for num in a:
        current_sum += num
        if current_sum > max_prefix:
            max_prefix = current_sum

    # Compute max_suffix
    current_sum = 0
    max_suffix = float('-inf')
    for num in reversed(a):
        current_sum += num
        if current_sum > max_suffix:
            max_suffix = current_sum

    total_sum = sum(a)

    if k == 1:
        return max_single
    else:
        if total_sum > 0:
            cross = max_prefix + max_suffix + (k - 2) * total_sum
        else:
            cross = max_prefix + max_suffix
        return max(max_single, cross)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3), 30)
    check(2, max_sub_array_sum_repeated([1, 2], 2, 3), 9)
    check(3, max_sub_array_sum_repeated([3,1,2], 3, 2), 12)
    check(4, max_sub_array_sum_repeated([5, -3,4],3,2), 12)

