def max_sum_increasing_subseq(a, n, index, k):
    i = index
    if i >= len(a) or k >= len(a):
        return 0  # Handle invalid indices if needed
    dp = []
    dp.append(a[0])
    for m in range(1, i + 1):
        max_val = a[m]
        for j in range(m):
            if a[j] < a[m] and dp[j] + a[m] > max_val:
                max_val = dp[j] + a[m]
        dp.append(max_val)
    target = a[k]
    max_prev = -float('inf')
    for m in range(i + 1):
        if a[m] < target:
            if dp[m] > max_prev:
                max_prev = dp[m]
    return max_prev + target if max_prev != -float('inf') else 0

