def max_sum_rectangular_grid(grid, n):
    if n == 0:
        return 0
    row0, row1 = grid[0], grid[1]
    prev0, prev1, prev2 = 0, row0[0], row1[0]
    for i in range(1, n):
        curr_row0 = row0[i]
        curr_row1 = row1[i]
        curr0 = max(prev0, prev1, prev2)
        curr1 = max(prev0 + curr_row0, prev2 + curr_row0)
        curr2 = max(prev0 + curr_row1, prev1 + curr_row1)
        prev0, prev1, prev2 = curr0, curr1, curr2
    return max(prev0, prev1, prev2)

