def modified_encode(alist):
    if not alist:
        return []
    groups = []
    current = alist[0]
    count = 1
    for elem in alist[1:]:
        if elem == current:
            count +=1
        else:
            groups.append((current, count))
            current = elem
            count = 1
    groups.append((current, count))
    result = []
    for elem, cnt in groups:
        if cnt == 1:
            result.append(elem)
        else:
            result.append([cnt, elem])
    return result

