import math

def get_Min_Squares(n):
    def is_perfect(x):
        s = int(math.sqrt(x))
        return s * s == x

    if is_perfect(n):
        return 1

    max_i = int(math.sqrt(n))
    for i in range(1, max_i + 1):
        rem = n - i*i
        if is_perfect(rem):
            return 2

    m = n
    while m % 4 == 0:
        m = m // 4
    return 4 if m % 8 == 7 else 3

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
