    check(2, get_Min_Squares(7), 4)
    check(3, get_Min_Squares(2), 2)
    check(4, get_Min_Squares(12), 3)
    check(5, get_Min_Squares(8), 2)
    check(6, get_Min_Squares(1), 1)

