def find_Divisor(x, y):
    start = min(x, y)
    end = max(x, y)
    max_count = -1
    result = -1
    for n in range(start, end +1):
        count = 0
        for i in range(1, n+1):
            if n % i == 0:
                count +=1
        if count > max_count or (count == max_count and n > result):
            max_count = count
            result = n
    return result

