def bin_coff(n, r=0):
    import math
    total = n + r
    if total % 2 != 0:
        return 0
    a = total // 2
    if a < 0 or a > n:
        return 0
    try:
        c1 = math.comb(n, a)
    except:
        return 0
    if a +1 > n:
        c2 = 0
    else:
        try:
            c2 = math.comb(n, a+1)
        except:
            c2 = 0
    return c1 - c2

