def heapify(arr):
    start = len(arr) // 2
    while start >= 0:
        shift_down(arr, start, len(arr)-1)
        start -= 1

def shift_down(arr, start, end):
    root = start
    while root * 2 + 1 <= end:
        child = root * 2 + 1
        if child + 1 <= end and arr[child] < arr[child +1]:
            child +=1
        if arr[root] < arr[child]:
            arr[root], arr[child] = arr[child], arr[root]
            root = child
        else:
            return

def heap_assending(nums):
    heapify(nums)
    end = len(nums) -1
    while end >0:
        nums[end], nums[0] = nums[0], nums[end]
        shift_down(nums, 0, end-1)
        end -=1
    return nums

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, heap_assending([18,14,10,9,8,7,9,3,2,4,1]), [1,2,3,4,7,8,9,9,10,14,18])
    check(2, heap_assending([12,2,4,5,2,3]), [2,2,3,4,5,12])
    check(3, heap_assending([]), [])
    check(4, heap_assending([5,1,3]), [1,3,5])
    check(5, heap_assending([3,1,2]), [1,2,3])

