def max_Product(arr):
    arr_len = len(arr)
    if arr_len < 2:
        return None
    x, y = arr[0], arr[1]
    for i in range(arr_len):
        for j in range(i + 1, arr_len):
            current = arr[i] * arr[j]
            if current > x * y:
                x, y = arr[i], arr[j]
    return (x, y)

