def breakSum(n):
    divisors = set()
    for i in range(1, int(n**0.5) +1):
        if n % i == 0:
            if i < n:
                divisors.add(i)
            counterpart = n // i
            if counterpart < n and counterpart != i:
                divisors.add(counterpart)
    sorted_divisors = sorted(divisors, reverse=True)
    selected = sorted_divisors[:3]
    return sum(selected)

