    check(4, breakSum(24), 26)

def group_tuples(Input):
    groups = {}
    order = []
    for tpl in Input:
        key = tpl[0]
        rest = tpl[1:]
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].extend(rest)
    result = []
    for k in order:
        merged = (k,) + tuple(groups[k])
        result.append(merged)
    return result

