def get_maxgold(gold, m, n):
    dp = [[0]*n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            current = gold[i][j]
            if i == 0 and j == 0:
                dp[i][j] = 0  # Exclude starting cell's value
            else:
                max_prev = 0
                if i > 0:
                    max_prev = max(max_prev, dp[i-1][j])
                if j > 0:
                    max_prev = max(max_prev, dp[i][j-1])
                dp[i][j] = current + max_prev
    return dp[m-1][n-1]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, get_maxgold([[1,3,1,5],[2,2,4,1],[5,0,2,3],[0,6,1,2]],4,4), 16)
