def max_profit(price, k):
    if not price or k == 0:
        return 0
    n = len(price)
    if k >= n // 2:
        max_p = 0
        for i in range(1, n):
            if price[i] > price[i-1]:
                max_p += price[i] - price[i-1]
        return max_p
    buy = [-float('inf')] * (k + 1)
    sell = [0] + [-float('inf')] * k
    for p in price:
        for t in range(k, 0, -1):
            buy[t] = max(buy[t], sell[t-1] - p)
            sell[t] = max(sell[t], buy[t] + p)
    return max(sell)

