def first_Factorial_Divisible_Number(x):
    if x == 1:
        return 1
    factors = prime_factors(x)
    max_n = 0
    for p, e in factors.items():
        current = find_min_n(p, e)
        if current > max_n:
            max_n = current
    return max_n

def prime_factors(x):
    factors = {}
    while x % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        x = x // 2
    i = 3
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 2
    if x > 1:
        factors[x] = 1
    return factors

def count_exponent(p, n):
    res = 0
    while n > 0:
        n = n // p
        res += n
    return res

def find_min_n(p, e):
    n = 0
    while True:
        n += 1
        if count_exponent(p, n) >= e:
            return n

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

