def min_cost(cost, m, n):
    rows = len(cost)
    if rows == 0:
        return 0
    cols = len(cost[0])
    dp = [[0]*cols for _ in range(rows)]
    dp[0][0] = cost[0][0]
    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + cost[0][j]
    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + cost[i][0]
    for i in range(1, rows):
        for j in range(1, cols):
            min_prev = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
            dp[i][j] = cost[i][j] + min_prev
    return dp[m][n]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, min_cost([[1,2,3],[4,8,2],[1,5,3]], 2,2), 8)
    check(2, min_cost([[1,1,1],[1,3,1],[1,1,1]], 2,2), 4)
    check(3, min_cost([[5]], 0,0),5)

def similar_elements(test_tup1, test_tup2):
    set2 = set(test_tup2)
    seen = set()
    result = []
    for elem in test_tup1:
        if elem in set2 and elem not in seen:
            result.append(elem)
            seen.add(elem)
    return tuple(result)

