    check(3, similar_elements((4,4,5,7), (5,4,8)), (4,5))
    check(4, similar_elements((1,2,3), (4,5)), ())
    check(5, similar_elements((), (1,2)), ())

def is_not_prime(n):
    if n <= 1:
        return True
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

