    check(4, is_not_prime(3), False)
    check(5, is_not_prime(9), True)
    check(6, is_not_prime(17), False)
    check(7, is_not_prime(0), True)
    check(8, is_not_prime(15), True)
    check(9, is_not_prime(5), False)

