def find_Rotations(str):
    n = len(str)
    for d in range(1, n + 1):
        if n % d != 0:
            continue
        part = str[:d]
        if part * (n // d) == str:
            return d
    return n

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, find_Rotations('aaaa'), 1)
    check(2, find_Rotations('abab'), 2)
    check(3, find_Rotations('abcabc'), 3)
    check(4, find_Rotations('abcd'), 4)
    check(5, find_Rotations('aaa'), 1)
    check(6, find_Rotations('a'), 1)
    check(7, find_Rotations('ababab'), 2)

